            logger.warning("No Anthropic API key - using mock gateway")
            return MockGateway()
        return AnthropicGateway(api_key=cfg.anthropic_api_key)
    else:
        if not cfg.openai_api_key:
            logger.warning("No OpenAI API key - using mock gateway")
            return MockGateway()
        return OpenAIGateway(
            api_key=cfg.openai_api_key,
            default_model=cfg.default_model,
        )


@asynccontextmanager
async def lifespan(app: FastAPI):
    """Application lifespan - initialize on startup."""
    global config, model_gateway

    config = get_config()

    # Set log level
    log_level = getattr(logging, config.log_level.upper(), logging.INFO)
    logging.getLogger().setLevel(log_level)

    # Initialize model gateway
    model_gateway = create_model_gateway(config)

    logger.info(f"SAK Router starting on port {config.port}")
    logger.info(f"Session Manager URL: {config.session_manager_url}")
    logger.info(f"Artifact Assembler URL: {config.artifact_assembler_url}")
    logger.info(f"Default model provider: {config.default_provider}")

    yield

    logger.info("SAK Router shutting down")


app = FastAPI(
    title="SAK Router",
    description="Routing gateway for backend services",
    version="1.0.0",
    lifespan=lifespan,
)


# -----------------------------------------------------------------------------
# Error Handling
# -----------------------------------------------------------------------------


def error_response(code: str, message: str, status_code: int = 500) -> JSONResponse:
    """Create standardized error response."""
    return JSONResponse(
        status_code=status_code,
        content={
            "error": {
                "code": code,
                "message": message,
            }
        },
    )


# -----------------------------------------------------------------------------
# Health Check
# -----------------------------------------------------------------------------


@app.get("/health")
async def health_check() -> dict[str, Any]:
    """
    Health check endpoint.

    Checks connectivity to all upstream services.
    """
    session_status = await check_service_health(
        f"{config.session_manager_url}/health"
    )
    assembler_status = await check_service_health(
        f"{config.artifact_assembler_url}/health"
    )

    # Model gateway is healthy if initialized
    gateway_status = "healthy" if model_gateway else "unhealthy"
    if isinstance(model_gateway, MockGateway):
        gateway_status = "mock"

    return {
        "status": "healthy",
        "services": {
            "session_manager": session_status,
            "artifact_assembler": assembler_status,
            "model_gateway": gateway_status,
        },
    }


# -----------------------------------------------------------------------------
# Session Routes (Proxy to Session Manager)
# -----------------------------------------------------------------------------


@app.api_route("/sessions", methods=["POST"])
async def create_session(request: Request):
    """Create a new session."""
    url = f"{config.session_manager_url}/sessions"
    try:
        return await proxy_request(request, url)
    except ServiceUnavailableError as e:
        return error_response("SERVICE_UNAVAILABLE", str(e), 503)


@app.api_route("/sessions/{session_id}", methods=["GET", "DELETE"])
async def session_by_id(session_id: str, request: Request):
